<?php $costTotals=$costSnapshot['sites'][$siteId] ?? ['total'=>0,'month_total'=>0,'count'=>0]; ?>
<section class="card website-costs" id="maintenance-costs">
<div class="section-heading"><div><h2>Maintenance &amp; running costs</h2><p class="muted">Hosting, domain renewals, maintenance and development for this website.</p></div></div>
<dl class="website-cost-totals"><div><dt>All recorded costs</dt><dd><?= money($costTotals['total']) ?></dd></div><div><dt><?= e(date('F Y',strtotime($costSnapshot['month'].'-01'))) ?></dt><dd><?= money($costTotals['month_total']) ?></dd></div><div><dt>Cost records</dt><dd><?= e($costTotals['count']) ?></dd></div></dl>
<div class="two-col">
<div><h3>Add a cost</h3><form class="form-grid" method="post" action="<?= e($sitePath) ?>/costs"><?= csrf_field() ?>
<label>Date<input name="date" type="date" value="<?= e(date('Y-m-d')) ?>" required></label><label>Cost type<select name="kind"><?php foreach(WebsiteCostService::KINDS as $key=>$label): ?><option value="<?= e($key) ?>"><?= e($label) ?></option><?php endforeach; ?></select></label>
<label>Amount (Rs.)<input name="amount" type="number" step="0.01" min="0.01" max="9999999999.99" required></label><label>Vendor / provider (optional)<input name="vendor" maxlength="120" placeholder="Hosting provider, registrar, developer..."></label>
<label class="full">Money account (optional)<select name="account_id"><option value="">Track website cost only</option><?php foreach($costAccounts as $account): ?><option value="<?= e($account['id']) ?>"><?= e($account['name']) ?> &middot; <?= money($account['balance']) ?></option><?php endforeach; ?></select></label>
<label class="full">Money category (if using an account)<select name="category_id"><?php foreach($costCategories as $category): ?><option value="<?= e($category['id']) ?>" <?= $category['name']==='Bills' ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label>
<p class="footnote full website-cost-note">Selecting an account also records this cost in Money and deducts it once. Website-only costs do not change account balances.</p>
<label class="full">Notes (optional)<textarea name="notes" rows="2" maxlength="1000"></textarea></label><div class="full"><button>Save website cost</button></div></form></div>
<div><div class="section-heading"><h3>Cost history</h3></div><form class="inline website-cost-filter" method="get" action="<?= e($sitePath) ?>#maintenance-costs"><label>Month<input name="cost_month" type="month" value="<?= e($costMonth ?? '') ?>"></label><button class="secondary">Show</button><a href="<?= e($sitePath) ?>?cost_month=all#maintenance-costs">All dates</a></form>
<?php if(!$costRecords): ?><p class="muted">No costs recorded for this period.</p><?php else: ?>
<div class="website-cost-list"><?php foreach($costRecords as $cost): ?><article class="website-cost-entry"><div class="section-heading"><div><strong><?= e(WebsiteCostService::KINDS[$cost['kind']]) ?></strong><small><?= e($cost['cost_date']) ?><?= $cost['vendor']!=='' ? ' &middot; '.e($cost['vendor']) : '' ?></small></div><strong><?= money($cost['amount']) ?></strong></div>
<?php if($cost['notes']!==''): ?><p><?= e($cost['notes']) ?></p><?php endif; ?>
<small><?php if($cost['expense_id']!==null): ?>Recorded in Money &middot; <?= e($cost['money_account']) ?> &middot; <a href="/salary?month=<?= e(substr($cost['cost_date'],0,7)) ?>">View expense</a><?php elseif($cost['money_recorded']): ?>Money entry removed; retained as a website-only cost.<?php else: ?>Website-only cost<?php endif; ?></small>
<form method="post" action="<?= e($sitePath) ?>/costs/<?= e($cost['id']) ?>/delete" data-confirm="<?= $cost['expense_id']!==null ? 'Remove this cost and reverse its linked Money expense?' : 'Remove this website cost?' ?>"><?= csrf_field() ?><button class="delete">Remove cost</button></form></article><?php endforeach; ?></div><p class="footnote">Up to 100 recent entries are shown for this period. Totals include all recorded costs.</p>
<?php endif; ?></div></div></section>
